const hardwareSlides=[{"title": "Hardware und Software arbeiten zusammen", "sub": "Zwei Begriffe – zwei Aufgaben", "body": "Hardware sind alle körperlichen Geräte und Bauteile eines Computers. Software sind Programme, die auf der Hardware ausgeführt werden. Ohne passende Software kann ein Computer viele Aufgaben nicht erledigen.", "images": ["monitor", "keyboard", "writer"], "caption": "Bildschirm und Tastatur: Hardware. Textprogramm: Software.", "note": "Hardware kann man anfassen. Software besteht aus Programmen."}, {"title": "Hardware außerhalb des Computers", "sub": "Was siehst du am Arbeitsplatz?", "body": "Zum Computerarbeitsplatz gehören zum Beispiel Bildschirm, Tastatur, Maus und Drucker. Diese Geräte befinden sich außerhalb des Computergehäuses und werden oft als Peripheriegeräte bezeichnet.", "images": ["monitor", "keyboard", "mouse", "printer"], "caption": "Vier Beispiele für äußere Hardware.", "note": "Äußere Hardware ist nicht dasselbe wie innere Bauteile."}, {"title": "Hardware im Inneren des Computers", "sub": "Ein Blick in das Gehäuse", "body": "Öffnet man das Gehäuse eines Desktop-PCs, findet man verschiedene Bauteile: Prozessor, Arbeitsspeicher, Hauptplatine und einen Datenspeicher wie eine SSD. Sie haben unterschiedliche Aufgaben und arbeiten zusammen.", "images": ["cpu", "ssd"], "caption": "Links: Prozessor (CPU). Rechts: SSD als Datenspeicher.", "note": "Auch unsichtbare Bauteile im Gehäuse gehören zur Hardware."}, {"title": "Was macht der Prozessor?", "sub": "CPU – die Recheneinheit", "body": "Der Prozessor (CPU) verarbeitet Befehle und führt Berechnungen aus. Er arbeitet sehr schnell und steuert viele Abläufe im Computer. Er ist nicht dasselbe wie der gesamte Computer.", "images": ["cpu"], "caption": "Der Prozessor wird auf der Hauptplatine eingebaut.", "note": "CPU = Central Processing Unit (Prozessor)."}, {"title": "Arbeitsspeicher und Datenspeicher", "sub": "Zwei verschiedene Aufgaben", "body": "Der Arbeitsspeicher (RAM) hält Daten und Programme bereit, die gerade benutzt werden. Beim Ausschalten gehen seine Inhalte normalerweise verloren. Eine SSD speichert Dateien und Programme dagegen auch nach dem Ausschalten.", "images": ["ssd"], "caption": "Die SSD ist ein dauerhafter Datenspeicher. RAM ist ein anderer Bauteiltyp.", "note": "RAM: vorübergehend. SSD: dauerhaft."}, {"title": "Hauptplatine und Stromversorgung", "sub": "Damit alles verbunden ist", "body": "Die Hauptplatine (Mainboard) verbindet Prozessor, Arbeitsspeicher und weitere Bauteile. Das Netzteil versorgt den PC mit elektrischer Energie. Ohne diese Teile könnte der Rechner nicht wie vorgesehen arbeiten.", "images": ["cpu"], "caption": "Der Prozessor sitzt auf der Hauptplatine. Das Netzteil liefert Strom.", "note": "Die Hauptplatine verbindet; das Netzteil versorgt."}, {"title": "Überprüfe dein Wissen", "question": "Welches Bauteil speichert Dateien auch nach dem Ausschalten?", "choices": ["Arbeitsspeicher (RAM)", "SSD", "Prozessor (CPU)"], "answer": 1, "hint": "Denke an den Unterschied zwischen vorübergehend und dauerhaft.", "why": "Eine SSD speichert Daten auch ohne Strom."}, {"title": "Was ist Software?", "sub": "Programme für verschiedene Aufgaben", "body": "Software besteht aus Programmen und ihren Anweisungen. Ein Textprogramm hilft beim Schreiben, ein Browser zeigt Webseiten und ein Zeichenprogramm hilft beim Malen. Diese Programme sind keine körperlichen Bauteile.", "images": ["writer", "browser", "paint"], "caption": "Textverarbeitung, Browser und Zeichenprogramm sind Beispiele für Software.", "note": "Software = Programme und Anweisungen."}, {"title": "Das Betriebssystem", "sub": "Die Grundlage für andere Programme", "body": "Ein Betriebssystem ist eine besondere Software. Es startet beim Hochfahren des Computers und sorgt dafür, dass Programme mit der Hardware zusammenarbeiten können. Bekannte Beispiele sind Windows, Linux und macOS.", "images": ["monitor", "writer"], "caption": "Das Betriebssystem stellt die Arbeitsumgebung bereit; darin laufen Programme.", "note": "Das Betriebssystem gehört zur Software."}, {"title": "Was macht das Betriebssystem genau?", "sub": "Vier wichtige Aufgaben", "body": "1. Es verwaltet Dateien und Ordner. 2. Es ermöglicht das Starten und Wechseln von Programmen. 3. Es steuert die Zusammenarbeit mit Geräten wie Druckern. 4. Es verwaltet Arbeitsspeicher und andere Computerressourcen.", "images": ["monitor", "printer", "ssd"], "caption": "Dateien verwalten, Programme starten und Geräte nutzen: Das Betriebssystem hilft dabei.", "note": "Das Betriebssystem organisiert die Arbeit des Computers."}, {"title": "Programme und Betriebssystem unterscheiden", "sub": "Nicht jedes Programm ist ein Betriebssystem", "body": "Ein Textprogramm ist ein Anwendungsprogramm: Du nutzt es für eine bestimmte Aufgabe. Das Betriebssystem schafft die Grundlage dafür, dass du das Textprogramm starten, speichern und bedienen kannst.", "images": ["writer", "monitor"], "caption": "Das Textprogramm ist eine Anwendung; das Betriebssystem verwaltet die Arbeitsumgebung.", "note": "Betriebssystem und Anwendungsprogramm sind beide Software."}, {"title": "Zwischenfrage: Betriebssystem", "question": "Welche Aufgabe gehört zu einem Betriebssystem?", "choices": ["Es ist ein Kabel im Gehäuse.", "Es verwaltet Dateien und ermöglicht das Starten von Programmen.", "Es druckt ohne Drucker Papier aus."], "answer": 1, "hint": "Denke daran, wer die Arbeit der Programme und Geräte organisiert.", "why": "Das Betriebssystem verwaltet Dateien, Programme und Hardware-Ressourcen."}, {"title": "Hardware und Software im Alltag", "sub": "Ein Beispiel: einen Text speichern", "body": "Du schreibst mit einem Textprogramm (Software). Die Tastatur (Hardware) und der Bildschirm (Hardware) helfen bei der Bedienung. Das Betriebssystem (Software) ermöglicht das Speichern der Datei auf der SSD (Hardware).", "images": ["keyboard", "writer", "ssd"], "caption": "Hardware und Software ergänzen sich beim Schreiben und Speichern.", "note": "Für eine Aufgabe braucht man oft mehrere Bauteile und Programme."}, {"title": "Zwischenfrage: innen oder außen?", "question": "Welche Aussage ist richtig?", "choices": ["Der Prozessor gehört zur inneren Hardware.", "Der Browser ist ein Bauteil im Gehäuse.", "Eine SSD ist ein Textprogramm."], "answer": 0, "hint": "Unterscheide Bauteile von Programmen.", "why": "Die CPU ist ein körperliches Bauteil im Inneren des Computers."}, {"title": "Das solltest du erklären können", "sub": "Zusammenfassung", "body": "Hardware: anfassbare Geräte und Bauteile. Äußere Hardware: zum Beispiel Bildschirm, Maus und Tastatur. Innere Hardware: zum Beispiel Prozessor, RAM, SSD und Hauptplatine. Software: Programme. Betriebssystem: verwaltet Dateien, Programme und Geräte.", "images": ["monitor", "cpu", "browser"], "caption": "Äußere Hardware – innere Hardware – Software.", "note": "Jetzt kannst du die Begriffe in eigenen Worten erklären."}];
