// Algorithmen: zwei Lernkapitel, Zusammenfassung, drei Übungsbereiche und gemeinsamer Test
const algoGeneralSlides=[{"title": "Algorithmen begegnen dir überall", "body": "Ein Rezept, eine Bauanleitung und das Zähneputzen bestehen aus Schritten, die ein Ziel erreichen. Auch ohne Computer kannst du Algorithmen ausführen.", "visual": "🍳 → 🥣 → 🥞"}, {"title": "Was ist ein Algorithmus?", "body": "Ein Algorithmus ist eine genaue Folge von Anweisungen, mit der eine Aufgabe gelöst wird. Das Buch nennt drei Bedingungen: Eindeutigkeit, Ausführbarkeit und Endlichkeit. Die sinnvolle Reihenfolge gehört zur Eindeutigkeit; das Übungsheft betont sie mit „Schritt für Schritt“.", "visual": "1 → 2 → 3 → Ziel"}, {"title": "Was ist kein Algorithmus?", "body": "„Mach irgendetwas Schönes“ ist unklar. „Nimm ein Blatt, zeichne einen Kreis und male ihn aus“ beschreibt dagegen konkrete Schritte.", "visual": "❓  →  ✅"}, {"title": "Wissenscheck", "question": "Welche Anweisung ist eindeutig?", "choices": ["Mach etwas Leckeres.", "Lege zwei Scheiben Brot auf einen Teller.", "Mach schnell!"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Eindeutigkeit: klare Anweisungen", "body": "Jede Anweisung muss klar verständlich sein. Wer den Algorithmus ausführt, darf nicht raten müssen, was gemeint ist.", "visual": "🔎 Klar statt ungenau"}, {"title": "Ausführbarkeit: sinnvolle Schritte", "body": "Jede Anweisung muss sinnvoll und tatsächlich ausführbar sein. Beim Pfannkuchenmachen werden Eier zuerst aufgeschlagen und nicht mit Schale in den Teig gegeben. Ein Ablauf muss außerdem eindeutig und endlich sein.", "visual": "🛠️ Kann ich das tun?", "sub": "Eine der drei Bedingungen aus dem Buch"}, {"title": "Endlichkeit: ein erreichbares Ende", "body": "Ein Algorithmus muss nach endlich vielen Schritten enden. Er benötigt ein klares Ziel und eine Möglichkeit, fertig zu werden.", "visual": "🏁 Start → Schritte → Ende"}, {"title": "Wissenscheck", "question": "Welche Eigenschaft fehlt bei „Wiederhole für immer“?", "choices": ["Eindeutigkeit", "Endlichkeit", "Ausführbarkeit"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Anweisungen in richtiger Reihenfolge", "body": "Beim Teekochen brauchst du mehrere klare Schritte: Wasser in den Wasserkocher füllen, Wasser erhitzen, einen Teebeutel in eine Tasse legen, heißes Wasser eingießen und den Tee ziehen lassen. Im Übungsheft schreibst du dafür mindestens fünf Schritte auf.", "visual": "① Wasser  ② Einschalten  ③ Aufgießen"}, {"title": "Die Sequenz", "body": "Schritt für Schritt bedeutet: Die Anweisungen stehen in einer festen Reihenfolge. Eine solche Folge heißt Sequenz. Die Schritte werden nacheinander ausgeführt; keiner wird übersprungen.", "visual": "A → B → C"}, {"title": "Algorithmen prüfen", "body": "Prüfe die drei Bedingungen aus dem Buch: Sind Anweisungen und Reihenfolge eindeutig? Ist jeder Schritt sinnvoll ausführbar? Hat der Ablauf ein klares Ende? Das Übungsheft hebt die feste Reihenfolge als „Schritt für Schritt“ hervor.", "visual": "✓ eindeutig  ✓ ausführbar  ✓ endlich"}, {"title": "Wissenscheck", "question": "Was ist eine Sequenz?", "choices": ["Eine zufällige Auswahl", "Eine Abfolge von Anweisungen", "Ein Computerbauteil"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Fehlerdetektiv", "body": "Beim Schuheanziehen kommt zuerst die Socke und dann der Schuh. Wenn du Schritte vertauschst, kann der Ablauf scheitern.", "visual": "🧦 → 👟"}, {"title": "Algorithmen selbst entwickeln", "body": "Zerlege eine Aufgabe in kleine Schritte. Formuliere jeden Schritt als klare Handlungsanweisung und überprüfe die Reihenfolge.", "visual": "📝 Planen → Prüfen → Verbessern"}, {"title": "Wissenscheck", "question": "Welche Anleitung ist am besten?", "choices": ["Bereite etwas vor.", "Mach das irgendwann.", "Stelle die Tasse hin und lege einen Teebeutel hinein."], "answer": 2, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Pfannkuchen: eine Sequenz", "body": "Die Buchseite zeigt eine feste Folge von Arbeitsschritten: Zutaten vorbereiten und verrühren, Öl erhitzen, Teig in die Pfanne geben, verteilen, wenden und fertig ausbacken. Vor dem Braten muss das Öl in der Pfanne sein. Die Abbildung fasst die Buchanleitung zusammen.", "visual": "Zutaten → Teig → Pfanne → Pfannkuchen"}, {"title": "Händewaschen: klare Befehle", "body": "Beschreibe die Bilder aus M1 mit eindeutigen Anweisungen in der Befehlsform. Das Buch gibt den Anfang „Halte eine Hand unter den Seifenspender“ vor. Beschreibe dann Wasser, Einreiben, Abspülen und Abtrocknen. Überlege, welche Schritte vertauschbar sind und welche nicht.", "visual": "Seife → Wasser → Einreiben → Abspülen → Abtrocknen"}, {"title": "Vom Algorithmus zum Programm", "body": "Ein Ablauf wird in kleine, genaue Teilschritte zerlegt. Für einen Computer werden die Anweisungen in einer Programmiersprache formuliert; so entsteht ein Programm. Das Buch erklärt außerdem das EVA-Prinzip: Eingabe → Verarbeitung → Ausgabe. Beim Sortieren: Zahlen eingeben, sortieren, sortierte Zahlen ausgeben.", "visual": "Algorithmus → Programmiersprache → Programm"}, {"title": "Du kannst Algorithmen erkennen!", "body": "Du kennst Definition, Eigenschaften und Sequenzen. Jetzt kannst du eigene Anweisungsfolgen prüfen und verbessern.", "visual": "🏆"}];
const algoDisplaySlides=[{"title": "Warum Algorithmen darstellen?", "body": "Ein Ablaufplan zeigt eine Anweisungsfolge übersichtlich. Pfeile zeigen, in welcher Reihenfolge die Schritte ausgeführt werden.", "visual": "Start ↓ Aktion ↓ Ende"}, {"title": "Ein einfacher Ablaufplan", "body": "Lies das vollständige Zähneputzen-Beispiel aus dem Übungsheft von oben nach unten: Zwischen Start und Ende stehen sechs Aktionen. Jede Aktion hat ein eigenes Rechteck; die Pfeile legen ihre Reihenfolge fest. „3 Minuten putzen“ ist hier eine Anweisung im Beispiel.", "visual": "(Start) → [Schritt 1] → [Schritt 2] → (Ende)"}, {"title": "Das Oval", "body": "Das Oval steht für Start oder Ende. Jeder vollständige Ablauf braucht einen Startpunkt und einen Endpunkt.", "visual": "⬭ Start     ⬭ Ende"}, {"title": "Das Rechteck", "body": "Im Rechteck steht eine Aktion: zum Beispiel „Zahnbürste nehmen“. Eine Aktion pro Rechteck ist besonders übersichtlich.", "visual": "▭ Zahnbürste nehmen"}, {"title": "Wissenscheck", "question": "Welches Symbol steht für eine Aktion?", "choices": ["Oval", "Rechteck", "Raute"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Die Pfeile", "body": "Pfeile verbinden die Symbole und legen die Richtung des Ablaufs fest. Ohne Pfeile ist die Reihenfolge unklar.", "visual": "⬭ ↓ ▭ ↓ ▭ ↓ ⬭"}, {"title": "Die Raute", "body": "Eine Raute stellt eine Entscheidung dar. Darin steht eine Frage, die mit Ja oder Nein beantwortet wird.", "visual": "◇ Regnet es? ◇"}, {"title": "Wenn – dann – sonst", "body": "Wenn es regnet, nimm einen Regenschirm mit. Sonst nimm eine Sonnenbrille mit. Beide Wege führen anschließend zur Aktion „Zur Schule gehen“ und dann zum Ende. Die Frage in der Raute wird mit Ja oder Nein beantwortet.", "visual": "◇ Regnet es? → Ja: ☂️ / Nein: 🕶️"}, {"title": "Wissenscheck", "question": "Wie viele Ausgänge hat eine Ja/Nein-Entscheidung?", "choices": ["Einen", "Zwei", "Vier"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Flussdiagramme lesen", "body": "Beginne beim Start und folge den Pfeilen bis zum Ende. Zähle nur die Rechtecke als Aktionen: Das Zähneputzen-Diagramm aus dem Übungsheft hat sechs Aktionen. Start und Ende werden nicht mitgezählt. Bei einer Raute wählst du den passenden Ja- oder Nein-Weg.", "visual": "Start → Frage → Weg → Ende"}, {"title": "Flussdiagramme zeichnen", "body": "Beginne mit dem Oval „Start“ und beende den Ablauf mit dem Oval „Ende“. Jede Aktion bekommt ein eigenes Rechteck. Verbinde die Symbole mit Pfeilen. Im Übungsheft zeichnest du „Einen Schulranzen für morgen packen“ mit mindestens vier Aktionen. Wenn du Entscheidungen verwendest, beschrifte die Wege mit Ja und Nein.", "visual": "⬭  ▭  ◇  →"}, {"title": "Schleifen: etwas wiederholen", "body": "Eine Schleife wiederholt einen oder mehrere Schritte. Im Übungsheft lautet das Beispiel: Prüfe „Aufgaben fertig?“. Bei Nein löse eine Aufgabe und prüfe erneut. Bei Ja gehe spielen und beende den Ablauf. Der Rückpfeil zeigt zur erneuten Prüfung, nicht zum Ende.", "visual": "🔁 Wiederholen bis fertig"}, {"title": "Zählschleife und Bedingungsschleife", "body": "Zählschleife: Wiederhole zehnmal „Hampelmann machen“. Du weißt vorher, wie oft. Bedingungsschleife: Solange das Glas nicht voll ist, gieße weiter Wasser ein. Hier steht die Anzahl der Wiederholungen vorher nicht fest.", "visual": "5-mal 🔁  |  solange … 🔁"}, {"title": "Wissenscheck", "question": "Was ist eine Schleife?", "choices": ["Ein einmaliger Start", "Eine Wiederholung von Schritten", "Ein anderes Wort für Software"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Lineare Suche", "body": "Die Unterlagen suchen die 5 in [7, 3, 9, 1, 5, 8, 2]. Prüfe von links nach rechts: 7, 3, 9, 1, dann 5. Der Treffer liegt auf Position 5; die letzten beiden Karten werden nicht mehr geprüft. Ist eine gesuchte Zahl nicht vorhanden, endet die Suche erst nach der letzten Karte.", "visual": "7 | 3 | 9 | 1 | 5 | 8 | 2 → suche 5"}, {"title": "Bubble Sort", "body": "Vergleiche benachbarte Karten von links nach rechts und tausche sie, wenn die linke größer ist. Die Unterlagen beginnen mit [5, 2, 4, 1, 3]. Nach dem ersten Durchgang steht die 5 rechts: [2, 4, 1, 3, 5]. Das ist noch nicht vollständig sortiert. Beginne wieder links; erst ein kompletter Durchgang ohne Tausch beendet das Verfahren.", "visual": "5 2 4 → 2 5 4 → 2 4 5"}, {"title": "Insertion Sort", "body": "Die erste Karte gilt als sortierter Teil. Nimm jeweils die nächste Karte und füge sie an der richtigen Stelle ein. Aus [5, 2, 4, 1, 3] wird zunächst [2, 5, 4, 1, 3], dann [2, 4, 5, 1, 3], dann [1, 2, 4, 5, 3] und schließlich [1, 2, 3, 4, 5].", "visual": "5 | 2 4 → 2 5 | 4 → 2 4 5"}, {"title": "Wissenscheck", "question": "Bei welchem Verfahren vergleichst du benachbarte Karten und tauschst sie bei Bedarf?", "choices": ["Lineare Suche", "Bubble Sort", "Insertion Sort"], "answer": 1, "hint": "Überlege, welche Regel du gelernt hast.", "why": "Diese Antwort passt zur Erklärung."}, {"title": "Darstellungen sicher verstehen", "body": "Du kannst Ablaufpläne lesen, einfache Flussdiagramme zeichnen und Entscheidungen, Schleifen, Such- und Sortierverfahren erklären.", "visual": "🎯"}];
const algoSummarySlides=[{"title": "Das Wichtigste zu Algorithmen", "body": "Das Buch nennt Eindeutigkeit, Ausführbarkeit und Endlichkeit. Die Anweisungen müssen klar sein und in einer sinnvollen Reihenfolge stehen. Diese Schrittfolge heißt Sequenz; das Übungsheft betont „Schritt für Schritt“.", "visual": "Eindeutig · Ausführbar · Endlich"}, {"title": "Symbole und Pfeile", "body": "Oval: Start/Ende. Rechteck: Aktion. Raute: Ja/Nein-Entscheidung. Pfeile: Reihenfolge.", "visual": "⬭   ▭   ◇   →"}, {"title": "Drei Ablaufarten", "body": "Sequenz: nacheinander. Verzweigung: abhängig von einer Bedingung. Schleife: Schritte wiederholen.", "visual": "→   ◇   🔁"}, {"title": "Suchen und Sortieren", "body": "Lineare Suche prüft Karte für Karte. Bubble Sort tauscht Nachbarn. Insertion Sort fügt Karten in einen sortierten Teil ein.", "visual": "🔎  ⇄  ↳"}, {"title": "Bereit für den Test?", "body": "Prüfe die Begriffe, ordne Schritte und Symbole zu und übe auch die Anwendung an neuen Beispielen.", "visual": "🏁"}];
